package dev.fluidgore.blood;

import dev.fluidgore.config.GoreConfig;
import net.minecraft.resources.Identifier;
import net.minecraft.util.RandomSource;

/**
 * The blood atlas ({@code assets/fluidgore/textures/misc/blood.png}) is an 8x8 grid of 64px white/grey shapes.
 * The colour comes from the vertex colour, so one texture serves every blood colour and drying state.
 * The PNG is generated by {@code tools/GenerateTextures.java}.
 *
 * <p>Tiles 0-13 are marks, each a shape of its own: splats, a drop, prints. Drawn smooth they are used as they
 * are; at the game's own resolutions they are cut into the pixels of the block they lie on (see {@link MarkPixels}),
 * so which tile a mark gets never depends on {@link GoreConfig#bloodResolution}. Tiles from 16 are the fluid's own,
 * which cover their whole tile and repeat once a block (see {@code render/FluidRenderer}): one set drawn at 64 pixels
 * to a block from tile 16, the same at 32 from tile 24 and at 16 from tile 32 (see {@link #fine}).
 */
public final class BloodTextures {
	public static final Identifier ATLAS = Identifier.fromNamespaceAndPath("fluidgore", "textures/misc/blood.png");

	public static final int SPLAT_0 = 0;
	public static final int SPLAT_COUNT = 4;
	public static final int DROPLET = 6;
	/** The print of a shoe. The prints all point up the tile (see {@code Footprints}). */
	public static final int FOOTPRINT = 7;
	public static final int SMALL_SPLAT = 9;
	/** The print of a cloven hoof: a pig, a cow, a sheep, a goat. */
	public static final int PRINT_CLOVEN = 10;
	/** The print of a horse's hoof. */
	public static final int PRINT_HOOF = 11;
	public static final int PRINT_PAW = 12;
	/** The print of a bird's foot. */
	public static final int PRINT_BIRD = 13;
	/** The surface of standing blood. */
	public static final int FILM = 16;
	/** Blood soaked into a floor. */
	public static final int STAIN = 17;
	/** The cracks of a dried pool, clear between them. */
	public static final int CRUST = 18;
	/** Plain white. */
	public static final int FLAT = 19;
	/** Blood pouring down a face. */
	public static final int RIBBON = 20;
	/** Highlights on wet blood, clear between them. */
	public static final int SPARK = 21;
	/**
	 * Not a tile: a run of blood down a wall, which has no fixed shape. It is drawn as long as it has run so far (see
	 * {@code DecalManager#run}).
	 */
	public static final int RUN = -1;

	private static final int GRID = 8;
	/** Half a texel of inset so neighbouring tiles never bleed in. */
	private static final float INSET = 0.5F / 512.0F;

	private BloodTextures() {
	}

	/**
	 * The fluid tile {@code tile} (one of {@link #FILM}, {@link #STAIN}, {@link #CRUST}, {@link #RIBBON}, {@link #SPARK}) as
	 * drawn at {@code texels} pixels to a block; 0 or 64 is the finest.
	 */
	public static int fine(int tile, int texels) {
		return tile + (texels == 32 ? 8 : texels == 16 ? 16 : 0);
	}

	public static float u0(int tile) {
		return (tile % GRID) / (float) GRID + INSET;
	}

	public static float v0(int tile) {
		return (tile / GRID) / (float) GRID + INSET;
	}

	public static float span() {
		return 1.0F / GRID - 2.0F * INSET;
	}

	/** A random splat: what a drop leaves that came down hard. */
	public static int splat(RandomSource random) {
		return SPLAT_0 + random.nextInt(SPLAT_COUNT);
	}

	/** A drop in flight: round drawn smooth, a square pixel at the game's own resolutions. */
	public static int droplet() {
		return GoreConfig.get().bloodResolution.pixelArt() ? FLAT : DROPLET;
	}
}
